import sys
from bisect import bisect_left, bisect_right


def replay(n: int, events: list[tuple[str, int, int]]) -> list[bool]:
    """
    Offline dynamic connectivity:
      * every cable's lifetime is an interval of log positions,
      * time is compressed to the positions of the queries,
      * each cable interval is inserted into a segment tree over query indices,
      * the tree is walked depth-first with a union-find that supports rollback,
        so every query is answered in the exact state of the fabric at its time.
    Total work is about O((E + Q) * log Q * log n), independent of how big the
    connected components are or how often cables are pulled and re-patched.
    """
    m = len(events)

    # ---- collect queries and their positions in the log -------------------
    qpos = []
    queries = []
    for i, (t, a, b) in enumerate(events):
        if t == "query":
            qpos.append(i)
            queries.append((a, b))
    Q = len(queries)
    if Q == 0:
        return []
    ans = [False] * Q

    # ---- build the lifetime intervals of every cable ----------------------
    active = {}          # normalised pair -> log index where it was patched in
    intervals = []       # (a, b, first_query_idx, last_query_idx)

    def add_interval(a, b, s, e):
        lo = bisect_left(qpos, s)
        hi = bisect_right(qpos, e) - 1
        if lo <= hi:
            intervals.append((a, b, lo, hi))

    for i, (t, a, b) in enumerate(events):
        if t == "query" or a == b:
            continue
        if a > b:
            a, b = b, a
        key = a * n + b
        if t == "link":
            if key not in active:
                active[key] = i
        else:  # unlink
            s = active.pop(key, None)
            if s is not None:
                add_interval(a, b, s, i - 1)
    for key, s in active.items():
        add_interval(key // n, key % n, s, m - 1)

    # ---- segment tree over query indices ----------------------------------
    size = 1
    while size < Q:
        size <<= 1
    seg = [None] * (2 * size)
    for a, b, lo, hi in intervals:
        l = lo + size
        r = hi + size + 1
        e = (a, b)
        while l < r:
            if l & 1:
                if seg[l] is None:
                    seg[l] = [e]
                else:
                    seg[l].append(e)
                l += 1
            if r & 1:
                r -= 1
                if seg[r] is None:
                    seg[r] = [e]
                else:
                    seg[r].append(e)
            l >>= 1
            r >>= 1

    # ---- union-find with rollback (union by size, no path compression) ----
    parent = list(range(n))
    comp = [1] * n
    stack = []  # roots that were attached under another root, in order

    sys.setrecursionlimit(max(1000, 64 + 4 * size.bit_length()))

    def dfs(node, lo, hi):
        saved = len(stack)
        edges = seg[node]
        if edges is not None:
            for a, b in edges:
                while parent[a] != a:
                    a = parent[a]
                while parent[b] != b:
                    b = parent[b]
                if a != b:
                    if comp[a] < comp[b]:
                        a, b = b, a
                    parent[b] = a
                    comp[a] += comp[b]
                    stack.append(b)
        if lo == hi:
            a, b = queries[lo]
            while parent[a] != a:
                a = parent[a]
            while parent[b] != b:
                b = parent[b]
            ans[lo] = (a == b)
        else:
            mid = (lo + hi) >> 1
            dfs(2 * node, lo, mid)
            if mid + 1 < Q:
                dfs(2 * node + 1, mid + 1, hi)
        # rollback
        while len(stack) > saved:
            b = stack.pop()
            a = parent[b]
            comp[a] -= comp[b]
            parent[b] = b

    dfs(1, 0, size - 1)
    return ans


if __name__ == "__main__":
    ev = [("link", 0, 1), ("link", 1, 2), ("query", 0, 2), ("unlink", 1, 0),
          ("query", 0, 2), ("query", 2, 1), ("link", 0, 2), ("query", 0, 1)]
    print(replay(4, ev))  # [True, False, True, True]
